INSERT INTO `email_templates` (`sid`, `name`, `group`, `cc`, `subject`, `text`, `hidden`) VALUES
(13, 'Resume Posting Confirmation', 'listing', '', 'Votre CV a été posté avec succès', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour {$listing.user.FullName},</p>\r\n<p>&nbsp;</p>\r\n<p>Votre CV a &eacute;t&eacute; post&eacute; avec succ&egrave;s sur <a href=\"{$siteUrl}\">{$siteUrl}</a>.</p>\r\n<p>&nbsp;</p>\r\n<p>Vous pouvez mettre &agrave; jour&nbsp;&nbsp;votre CV &agrave; partir de la section&nbsp;<a href=\"{$siteUrl}/my-listings/resume/\">&nbsp;\"Mon compte\"</a>.</p>\r\n<p><br /><br /><br />Merci pour votre confiance,<br />L\'&nbsp;&eacute;quipe {$GLOBALS.settings.site_title}&nbsp;</p>', 0),
(14, 'Job Posting Confirmation', 'listing', '', 'Jobsquare.ma : Votre annonce a été activée', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour&nbsp; {$user.FullName},</p>\r\n<p><br /><br />Votre annonce&nbsp;<a href=\"{$siteUrl}{$listing|listing_url}\">{$listing.Title}</a>&nbsp; a<span id=\"result_box\" class=\"short_text\" lang=\"fr\"><span class=\"\"> &eacute;t&eacute; affich&eacute;e avec succ&egrave;s sur&nbsp;</span></span>&nbsp;<a href=\"{$siteUrl}\">{$siteUrl}</a>.</p>\r\n<p><br /><br />Vous pouvez modifier et g&eacute;rer cette offre d\'emploi &nbsp;&agrave; partir de la section <a href=\"{$siteUrl}/my-listings/job/\">\"Mon compte\"</a>&nbsp;.</p>\r\n<p>&nbsp;</p>\r\n<p><br />Merci pour votre confiance,</p>\r\n<p>L\'&nbsp;&eacute;quipe&nbsp;{$GLOBALS.settings.site_title}</p>', 0),
(17, 'Job Expiration Notice', 'listing', '', 'Votre  offre d\'emploi vient d\'expirer', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour&nbsp; {$listing.user.FullName},<br /><br />Votre annonce \"{$listing.Title}\"&nbsp;&nbsp;<span id=\"result_box\" class=\"short_text\" lang=\"fr\"><span class=\"\">vient d\'expirer.</span></span> <br /><br />Pour l\'activer &agrave; nouveau, allez &agrave; la section&nbsp; <a href=\"{$GLOBALS.user_site_url}/my-listings/\" data-cke-saved-href=\"{$GLOBALS.user_site_url}/my-listings/\">&nbsp;Offres d\' emploi</a>&nbsp;de&nbsp;\"Mon compte\".</p>\r\n<p><br /><br />Merci pour votre confiance,</p>\r\n<p>L\'&nbsp;&eacute;quipe&nbsp;{$GLOBALS.settings.site_title}</p>', 0),
(18, 'Resume Expiration Notice', 'listing', '', 'Votre CV a  été expiré', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour {$listing.user.FullName},<br /><br /> Votre CV vient d\'expirer .<br /><br /><span id=\"result_box\" class=\"\" lang=\"fr\"><span class=\"\">Pour le r&eacute;activer, allez dans la section Mes CV dans</span></span> <a href=\"{$siteUrl}/my-listings/resume/\">\"Mon compte\"</a>.<br /><br />Merci pour votre confiance,<br />L\'&nbsp;&eacute;quipe {$GLOBALS.settings.site_title}&nbsp;</p>', 0),
(22, 'Product Expiration Notice', 'product', '', 'Rappel à propos de l’expiration du produit', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour {$user.FullName},<br /><br />Votre produit \"{$product.caption}\" v<span id=\"result_box\" class=\"short_text\" lang=\"fr\"><span class=\"\">ient d\'expirer</span></span>.<br /><br /><span id=\"result_box\" class=\"\" lang=\"fr\"><span class=\"\">Pour acheter ce produit de nouveau ou un autre produit disponible, visitez notre</span></span>&nbsp; page&nbsp;<a href=\"{$siteUrl}{if $user.group.id == \'JobSeeker\'}/jobseeker-products/{elseif $user.group.id == \'Employer\'}/employer-products/{else}/products/{/if}\">Produit </a>.</p>\r\n<p><br />Merci pour votre confiance,<br />L\'&nbsp;&eacute;quipe {$GLOBALS.settings.site_title}&nbsp;</p>', 0),
(24, 'Order Confirmation', 'product', '', 'Votre commande  {$GLOBALS.settings.site_title}', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour&nbsp; {$user.FullName},<br /><br /><span id=\"result_box\" class=\"short_text\" lang=\"fr\"><span class=\"\">Vous avez achet&eacute; avec succ&egrave;s&nbsp;</span></span> (You have successfully purchased )\"{$product.caption}\" sur {$GLOBALS.settings.site_title}.<br /><span id=\"result_box\" class=\"short_text\" lang=\"fr\"></span></p>\r\n<p><span id=\"result_box\" class=\"short_text\" lang=\"fr\"><span class=\"\">D&eacute;tails de commande</span></span>:<br /><br />\"{$product.caption}\" x 1 = {currencyFormat amount=$product.price}<br />-----<br />Sous-total: {currencyFormat amount=$invoice.sub_total}<br />{if $invoice.tax}Taxes: {currencyFormat amount=$invoice.tax}<br />{/if} Total: {currencyFormat amount=$invoice.total}<br /><br /><a href=\"{$siteUrl}/invoice/{$invoice.id}/{$invoice.hash}/\">Voir la facture</a><br /><br />Merci pour votre confiance,<br />L\' &eacute;quipe {$GLOBALS.settings.site_title}&nbsp;</p>', 0),
(25, 'Product Purchase Confirmation for Admin', 'product', '', 'New payment received', 'Hello,<br /><br />On {$invoice.date|date} the user {$user.FullName} has successfully purchased &quot;{$product.caption}&quot; on {$GLOBALS.settings.site_title}.<br /><br />Payment details:<br /><br />&quot;{$product.caption}&quot; x 1 = {currencyFormat amount=$product.price}<br />-----<br />Sub total: {currencyFormat amount=$invoice.sub_total}<br />{if $invoice.tax}Taxes: {currencyFormat amount=$invoice.tax}<br />{/if}Grand total: {currencyFormat amount=$invoice.total}<br /><br />To view payment details, please click <a href=\"{$GLOBALS.admin_site_url}/view-invoice/?sid={$invoice.id}\">here</a>.\r\n', 1),
(30, 'Contact Form Email', 'other', '', 'Message from {$name}', 'This message was sent via contact form on <a href=\"{$siteUrl}\">{$siteUrl}</a>\r\n<br/><br/>\r\n|| name: {$name}<br/>\r\n|| email: {$email}<br/>\r\n|| comments: {$comments}', 1),
(33, 'Application Email to Employer', 'other', '', 'Nouvelle candidature pour  {$listing.Title}', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour&nbsp; {$user.FullName},</p>\r\n<p><br /><br />Vous avez re&ccedil;u une nouvelle candidature &agrave; votre poste&nbsp; &nbsp;\"{$listing.Title}\"&nbsp; du candidat suivant:<br /><br />Nom: {$applicant_request.name}<br />Email: {$applicant_request.email}<br /><br /><br />Merci pour votre confiance,<br />L\'&nbsp;&eacute;quipe&nbsp;{$GLOBALS.settings.site_title}</p>', 0),
(36, 'Password Recovery', 'other', '', 'Changer votre mot de passe  {$GLOBALS.settings.site_title}', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour {$user.FullName},<br /><br /><br />Pour changer votre mot de passe, veuillez utiliser le lien ci-dessous :<br /><br /><a href=\"{$siteUrl}/change-password/?username={$user.username}&amp;verification_key={$user.verification_key}\">Mot De Passe Oubli&eacute;&nbsp;</a></p>\r\n<p><br />Merci pour votre confiance,<br />L\'&nbsp;&eacute;quipe {$GLOBALS.settings.site_title}&nbsp;</p>', 0),
(48, 'Employer Welcome Email', 'user', '', 'Bienvenue sur  {$GLOBALS.settings.site_title}!', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour&nbsp; {$user.FullName},</p>\r\n<p><br /><br />Merci pour votre inscription sur&nbsp; {$siteUrl}&nbsp; vous pouvez publier vos annonces d&rsquo;emploi sur notre site.</p>\r\n<p><br />Nous tenons &agrave; vous informer que l\'activation de votre compte ainsi que la validation de vos annonces sont assur&eacute;s manuellement est ce dans le but de vous fournir autant de s&eacute;curit&eacute; et fiabilit&eacute; dans la mesure de vos attentes.</p>\r\n<p><br />Pour toute demande d&rsquo;assistance, notre &eacute;quipe vous accompagne et veille &agrave; optimiser toutes vos annonces.</p>\r\n<p>&nbsp;</p>\r\n<p>En plus de la publication gratuite, Jobsquare.ma met &agrave; votre disposition des packs publicitaires payants pour am&eacute;liorer la visibilit&eacute; de vos annonces et maximiser vos chances de trouver des CV pertinents correspondant &agrave; vos besoins de recrutement.<br />Pour plus d&rsquo;information concernant nos offres commerciales n&rsquo;h&eacute;sitez pas &agrave; contacter notre service commercial .</p>\r\n<p><br /><br />Merci pour votre confiance,</p>\r\n<p>L\'&nbsp;&eacute;quipe&nbsp;{$GLOBALS.settings.site_title}</p>\r\n<p><img src=\"https://www.jobsquare.ma/files/userfiles/logo-jobsquare.jpg\" alt=\"\" width=\"262\" height=\"72\" /></p>', 0),
(49, 'Job Seeker Welcome Email', 'user', '', 'Bienvenue sur {$GLOBALS.settings.site_title}!', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour&nbsp; {$user.FullName},</p>\r\n<p>&nbsp;</p>\r\n<p>Vous avez fait le premier pas pour obtenir un emploi sur&nbsp; {$siteUrl}.</p>\r\n<p><br />Maintenant vous cr&eacute;ez votre CV et vous le remplissez &agrave; 90% au minimum&nbsp;pour r&eacute;pondre aux offres qui correspondent &agrave; vos comp&eacute;tences et transf&eacute;rer votre CV en cliquant sur le bouton &laquo;POSTULER MAINTENANT&raquo;.</p>\r\n<p>Mettez-le &agrave; jour r&eacute;guli&egrave;rement afin d&rsquo;optimiser vos chances d&rsquo;&ecirc;tre contact&eacute; par les entreprises.</p>\r\n<p><br />Vous pouvez ainsi acc&eacute;l&eacute;rer votre recherche en inscrivant dans les Alertes Emploi jobsquare.ma vous recevez de nouvelles offres dans votre bo&icirc;te de r&eacute;ception et soyez l\'un des premiers &agrave; postuler.</p>\r\n<p><br />D&eacute;couvrez &eacute;galement nos Blogs de nombreux conseils pour faciliter vos recherches!</p>\r\n<p>&nbsp;Et n\'oubliant pas de visiter notre rubrique formation &agrave; ceux qui veulent acqu&eacute;rir de nouvelles comp&eacute;tences dans tous les secteurs</p>\r\n<p>&nbsp;</p>\r\n<p>Pour toute autre pr&eacute;cision ou demande d\'assistance, n\'h&eacute;sitez pas &agrave; nous contacter&nbsp;<br />Merci pour votre confiance,</p>\r\n<p>L\'&nbsp;&eacute;quipe&nbsp;{$GLOBALS.settings.site_title}</p>\r\n<p>&nbsp;</p>', 0),
(203, 'Job Alert', 'alerts', '', '{$GLOBALS.settings.site_title}: Alerte Emploi', '<p>&nbsp;</p>\r\n<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour,<br /><br />Voici <span id=\"result_box\" class=\"\" lang=\"fr\"><span class=\"\"> les derni&egrave;res</span></span> offres d\'emploi publi&eacute;es sur Jobsquare.ma qui pourraient vous int&eacute;resser:</p>\r\n<p>{foreach from=$listings item=listing}</p>\r\n<p><strong><a href=\"{$siteUrl}{$listing|listing_url}\">{$listing.Title}</a></strong><br />{$listing|location}<br />{$listing.user.CompanyName}</p>\r\n<p>{/foreach}</p>\r\n<p><span id=\"result_box\" class=\"\" lang=\"fr\"><span class=\"\">Si vous ne souhaitez plus recevoir d\'alertes par courrier &eacute;lectronique, veuillez vous d&eacute;sabonner en utilisant le lien ci-dessous</span></span>:<br /><a href=\"{$siteUrl}/guest-alerts/unsubscribe/?key={$key}\">Se d&eacute;sabonner</a>.</p>\r\n<p><br />Merci pour votre confiance,</p>\r\n<p>L\'&nbsp;&eacute;quipe&nbsp;{$GLOBALS.settings.site_title}</p>', 0),
(301, 'Admin Invite', 'other', '', 'You\'ve been invited to manage {$GLOBALS.settings.site_title} job board', '<p>Hi {$admin.name},</p>\n<p>{$inviter.name} has invited you to work on {$GLOBALS.settings.site_title} job board.</p>\n<p><a target=\"_blank\" href=\"{$GLOBALS.admin_site_url}/?action=activate&amp;email={$admin.email|escape:\"url\"}&amp;hash={$admin.hash|escape:\"url\"}\">Create Admin Account</a></p>\n<p style=\"text-align: center;\"><a href=\"https://www.smartjobboard.com/?utm_source=Invite&amp;utm_medium=Email&amp;utm_campaign=Invite_Emails\"><img class=\"logo__img\" src=\"https://www.smartjobboard.com/wp-content/uploads/2016/09/logo.png\" border=\"0\" /></a></p>', 1),
(302, 'Admin Recover', 'other', '', 'Password Reset', '<p>Hi {$admin.name},</p>\n<p>You recently requested to reset your password for {$GLOBALS.settings.site_title}. Please click the link below to reset your password.</p>\n<p><a target=\"_blank\" href=\"{$GLOBALS.admin_site_url}/?action=password_recover&amp;recover_key={$admin.recover_key|escape:\"url\"}\">{$GLOBALS.admin_site_url}/?action=password_recover&amp;recover_key={$admin.recover_key|escape:\"url\"}</a></p>\n<p>If clicking the link does not work, please copy and paste the URL into your browser instead.</p>', 1),
(303, 'Recurring Payment Failed', 'product', '', 'Paiement échoué', '<p>&nbsp;</p>\r\n<p>Bonjour&nbsp;{$user.FullName},</p>\r\n<p>Votre paiement r&eacute;current pour \"{$product.caption}\"&nbsp;sur {$GLOBALS.settings.site_title}</p>\r\n<p>a&nbsp;&eacute;t&eacute; &eacute;chou&eacute;.</p>\r\n<p>L\'abonnement est maintenant annul&eacute;.</p>\r\n<p>D&eacute;tails de paiement&nbsp;: \"{$product.caption}\" - {currencyFormat amount=$product.price}&nbsp;<br /><br /></p>\r\n<p>----</p>\r\n<p>Sous- total: {currencyFormat amount=$invoice.sub_total}</p>\r\n<p>{if $invoice.tax} TTC: {currencyFormat amount=$invoice.tax} {/if}</p>\r\n<p>Total: {currencyFormat amount=$invoice.total}</p>\r\n<p>Assurez-vous que votre carte de cr&eacute;dit / d&eacute;bit ait suffisamment du&nbsp;solde disponible&nbsp; et que votre carte n\'est pas expir&eacute;e.</p>\r\n<p>Vous pouvez renouveler votre abonnement en vous souscrivant &agrave; nouveau sur notre site.</p>\r\n<p><br />Merci pour votre confiance,<br />L\'&nbsp;&eacute;quipe&nbsp;{$GLOBALS.settings.site_title}</p>', 0),
(304, 'Contact_message', 'other', '', 'Message concernant votre candidature - {$listing.Title}', '<p><img title=\"Emploi Maroc, Formation Maroc, Travail Maroc\" src=\"http://85.25.46.94/projects/JobsquareMa/templates/Jobsquarev7/assets/images/logo-jobsquare.jpg\" alt=\"Emploi Maroc, Formation Maroc, Travail Maroc\" width=\"368\" height=\"92\" /></p>\r\n<p>Bonjour {$applicant_request.name},</p>\r\n<p><br />Nous avons bien re&ccedil;u votre candidature pour le poste \"{$listing.Title}\" et nous vous remercions de l\'int&eacute;r&ecirc;t que vous portez &agrave; notre entreprise.</p>\r\n<p><br />Voici un message de notre &eacute;quipe de recrutement :</p>\r\n<div style=\"background-color: #f8f9fa; padding: 15px; border-left: 4px solid #007bff; margin: 20px 0;\">{$applicant_request.message}</div>\r\n<p><br />Nous vous recontacterons prochainement concernant votre candidature.</p>\r\n<p><br />Cordialement,<br /> {$user.FullName}<br /> &Eacute;quipe de recrutement - {$GLOBALS.settings.site_title}</p>', 0);
