INSERT INTO `settings` (`sid`, `name`, `value`) VALUES
(1238, 'theme_custom_css_Jobsquare', '@media (min-width:1024px) {\r\n    .container {\r\n        max-width: 1170px;\r\n    }\r\n}\r\n\r\nbody {\r\n    font-family: \"Open Sans\", sans-serif;\r\n    font-size: 14px;\r\n    background: #fff;\r\n    overflow-x: hidden\r\n}\r\n.listing-item__title a {\r\n    color:#009688;\r\n   \r\n}\r\n\r\n.link,\r\na {\r\n    color:#ed174b;\r\n    text-decoration: none !important;\r\n}\r\n\r\n.link:hover,\r\n.link:focus {\r\n    text-decoration: none !important;\r\n}\r\n\r\n.view-all,\r\n.view-all-training {\r\n    background: transparent;\r\n    padding: 30px 0 70px;\r\n}\r\n\r\n.view-all__btn {\r\n    width: 210px;\r\n    height: 50px;\r\n    border: 2px solid #ed174b;\r\n    border-radius: 0px;\r\n    line-height: 50px;\r\n    color: #ed174b;\r\n    -webkit-transition: all 0.2s ease-in;\r\n    -moz-transition: all 0.2s ease-in;\r\n    -o-transition: all 0.2s ease-in;\r\n    transition: all 0.2s ease-in;\r\n    font-size: 18px;\r\n}\r\n\r\n.view-all__btn:hover {\r\n    box-shadow: none;\r\n    background: #ed174b;\r\n    color: #fff;\r\n    border-color: #ed174b;\r\n}\r\n\r\n/***********************************/\r\n\r\n\r\n.navbar .navbar-right .login_btn {\r\n    background: #ffffff;\r\n    height: 40px;\r\n    line-height: 38px;\r\n    color: #ed174b;\r\n    padding: 0px 20px;\r\n    border: 1px solid #ed174b;\r\n    font-size: 15px;\r\n    font-weight: 600 !important;\r\n    border-radius: 4px;\r\n}\r\n\r\n.navbar .navbar-right .logout_btn {\r\n    background: #fff;\r\n    height: 25px;\r\n    line-height: 22px;\r\n    color: #fff;\r\n    padding: 0px 10px;\r\n    border: 1px solid #ed174b;\r\n    font-size: 16px\r\n}\r\n\r\n.navbar .navbar-right .signup_btn, .navbar .navbar-right .logout_btn, .navbar .navbar-right .navbar__item:first-child .navbar__link.logout_btn {\r\n    background:#ed174b17;\r\n    height: 25px;\r\n    line-height: 22px;\r\n    color:#ed174b;\r\n    padding: 0px 10px;\r\n    border: 1px solid transparent;\r\n    font-size: 14px;\r\n    height: 40px;\r\n    line-height: 38px;\r\n    border-radius: 4px;\r\n}\r\n\r\n.navbar .navbar-right .signup_btn {\r\n    background: #fff;\r\n    height: 40px;\r\n    line-height: 40px;\r\n    color: #005689;\r\n    border: 1px solid #005689;\r\n    padding: 0px 10px;\r\n    font-size: 16px;\r\n    font-weight: 600;\r\n    border-radius: 2px\r\n}\r\n\r\n.slide {\r\n    border-radius: 7px;\r\n    position: relative;\r\n    background: transparent;\r\n    background-size: cover;\r\n    height: 495px;\r\n    overflow: hidden;\r\n    background-image: url(templates/Jobsquare/assets/images/slide-home.jpg);\r\n}\r\n\r\n.slide img {\r\n    width: 100%;\r\n    display: block;\r\n    height: auto;\r\n}\r\n\r\n@media (max-width: 767px) {\r\n    .slide {\r\n        height: auto;\r\n    }\r\n\r\n    .featured-job-right {\r\n        display: none;\r\n    }\r\n}\r\n\r\n.test {\r\n    background-color: #f7f7f7;\r\n}\r\n\r\n.listing__latest-training .listing-item__title a,\r\n.listing__featured-training .listing-item__title a {\r\n    color: #108a00;\r\n}\r\n.form-control:focus {\r\n    border-color: #f0f8ff;\r\n    background: #ffffff;\r\n    outline: 0;\r\n    -webkit-box-shadow: none;\r\n    box-shadow: none;\r\n}\r\n\r\n.btn__white-training {\r\n    width: 210px;\r\n    height: 50px;\r\n    border: 2px solid #108a00;\r\n    border-radius: 0px;\r\n    line-height: 50px;\r\n    color: #108a00;\r\n    margin-bottom: 0px;\r\n}\r\n\r\n.btn__white-training:hover:not(disabled) {\r\n    color: white;\r\n    background-color: #108a00;\r\n}\r\n\r\n.listing__latest-training .listing-item__employment-type {\r\n    color: #108a00;\r\n    font-size: 16px;\r\n    font-weight: 400;\r\n}\r\n\r\n.btn {\r\n    font-size: 14px;\r\n}\r\n\r\n.pageinterne .search-header {\r\n    display: none\r\n}\r\n\r\n.pageinterne .quick-search__wrapper {\r\n    margin: 0;\r\n}\r\n\r\n.pageinterne .container .search-results .listing-item__featured:hover {\r\n    border-color: #2baee7;\r\n}\r\n\r\n.pageinterne .container-training .search-results .listing-item__featured:hover {\r\n    border-color: #2baee7;\r\n}\r\n\r\n.pageinterne .container .listing-item__title a {\r\n    color: #ed174b;\r\n}\r\n\r\n.pageinterne .container-training .listing-item__title a {\r\n    color: #108a00;\r\n}\r\n\r\n#login-form {\r\n    color: #a6a6a6\r\n}\r\n\r\n#login-form input[type=text],\r\n#login-form input[type=email],\r\n#login-form input[type=password],\r\n#login-form input:-webkit-autofill {\r\n    border: 1px solid #a6a6a6;\r\n    background: #fff;\r\n    border-radius: 3px;\r\n    padding: 15px;\r\n    -webkit-box-shadow: 0 0 0 30px white inset;\r\n    color: #a6a6a6 !IMPORTANT;\r\n    font-size: 18px;\r\n}\r\n\r\n#login-form .form-control {\r\n    border: 1px solid #a6a6a6;\r\n    background: #fff;\r\n    border-radius: 3px;\r\n    padding: 15px;\r\n    -webkit-box-shadow: 0 0 0 30px white inset;\r\n    color: #a6a6a6 !IMPORTANT;\r\n    font-size: 18px;\r\n}\r\n\r\n#login-form input[type=text]:hover,\r\n#login-form input[type=email]:hover,\r\n#login-form input[type=password]:hover,\r\n#login-form input:-webkit-autofill:hover,\r\n#login-form input[type=text]:focus,\r\n#login-form input[type=email]:focus,\r\n#login-form input[type=password]:focus,\r\n#login-form input:-webkit-autofill:focus {\r\n    color: #a6a6a6;\r\n    border: 1px solid #2caced;\r\n}\r\n\r\n#login-form .form-control:focus {\r\n    color: #a6a6a6;\r\n    border: 1px solid #2caced;\r\n}\r\n\r\n#login-form .form-group__btns .btn {\r\n    margin-right: 0;\r\n    font-size: 18px;\r\n    font-weight: 600;\r\n}\r\n\r\n#login-form input::-webkit-input-placeholder {\r\n    color: #a6a6a6;\r\n    font-weight: 300;\r\n    text-align: left !important\r\n}\r\n\r\n#login-form input:-moz-placeholder {\r\n    color: #a6a6a6;\r\n    font-weight: 300 !important;\r\n    text-align: left !important\r\n}\r\n\r\n/* FF 4-18 */\r\n#login-form input::-moz-placeholder {\r\n    color: #a6a6a6;\r\n    font-weight: 300 !important;\r\n    text-align: left !important\r\n}\r\n\r\n/* FF 19+ */\r\n#login-form input:-ms-input-placeholder {\r\n    color: #a6a6a6;\r\n    font-weight: 300 !important;\r\n    text-align: left !important\r\n}\r\n\r\n/* IE 10+ */\r\n.top-contact-infos {\r\n    min-height: 100px\r\n}\r\n\r\n.top-contact-infos table {\r\n    text-align: left;\r\n    margin-bottom: 30px\r\n}\r\n\r\n.static-pages .top-contact-infos td {\r\n    padding: 0 15px;\r\n    font-size: 18px\r\n}\r\n\r\n.static-pages .top-contact-infos th {\r\n    color:#ed174b;\r\n    font-size: 16px;\r\n    padding: 0 15px;\r\n    white-space: nowrap;\r\n}\r\n\r\n.static-pages .top-contact-infos img {\r\n    max-width: inherit;\r\n    height: auto !important;\r\n}\r\n\r\n/*@media (min-width:992px) {\r\nli.featured-company { min-width:238.4px}}*/\r\n\r\n\r\n.quick-search__find.btn__orange:hover {\r\n    background: #6c6c6c;\r\n}\r\n\r\n.my-account-listings .form-group__btn .btn.bouton__orange {\r\n    color: #fff;\r\n    font-size: 16px;\r\n    background: #ed174b;\r\n    border-radius: 5px;\r\n    font-size: 18px;\r\n}\r\n\r\n.my-account-listings .form-group__btn .btn.bouton__violet {\r\n    color: #fff;\r\n    font-size: 16px;\r\n    background: #108a00;\r\n    border-radius: 5px;\r\n    font-size: 18px;\r\n}\r\n\r\n@media (max-width: 767px) {\r\n    .navbar .navbar-nav.navbar-right .navbar__item {\r\n        display: inline-block;\r\n        padding: 0;\r\n        float: left;\r\n        width: 40%;\r\n        margin: 0px 2%;\r\n    }\r\n\r\n    .navbar .navbar-right .navbar__item:first-child .navbar__link {\r\n        color: #333;\r\n        padding: 0px 10px;\r\n        text-align: center;\r\n    }\r\n\r\n    .navbar .navbar-right .navbar__item .navbar__link.btn__blue {\r\n        color: #262626;\r\n        background: none;\r\n        padding: 0px 10px;\r\n        text-align: center;\r\n        color: #fff;\r\n        background-color:#ed174b;\r\n        border: 1px solid#ed174b;\r\n        height: auto;\r\n    }\r\n}\r\n\r\n.violet {\r\n    color: #108a00;\r\n}\r\n\r\n.c-orange {\r\n    color: #ed174b;\r\n}\r\n\r\n.listjob {}\r\n\r\n.listtraining {}\r\n\r\narticle.listing-item.listjob:hover {\r\n    border: 1px solid #ed174b;\r\n}\r\n\r\narticle.listing-item.listtraining:hover {\r\n    border: 1px solid #108a00;\r\n}\r\n\r\n.slogan {\r\n    color: #6e6c6e;\r\n    font-size: 13px;\r\n    font-weight: 400;\r\n    left: 0px;\r\n    letter-spacing: 0;\r\n    position: absolute;\r\n    top: 43px;\r\n    visibility: visible;\r\n    text-transform: none;\r\n    line-height: 24px;\r\n    text-transform: none;\r\n    white-space: nowrap;\r\n    letter-spacing: 2.4px;\r\n}\r\n.tinyheader .slogan {\r\n    left: 17px;\r\n    top: 34px;\r\n    font-size: 9px;\r\n    letter-spacing: .5px;\r\n}\r\n\r\n.c-violet {\r\n    background: #108a00;\r\n    border: 1px solid #108a00;\r\n}\r\n\r\n.c-violet:hover {\r\n    background: #7a5b93;\r\n    border: 1px solid #7a5b93;\r\n}\r\n\r\n@media (max-width: 767px) {\r\n    .slogan {\r\n        font-size: 13px;\r\n        left: 75px;\r\n        top: 44px;\r\n    }\r\n}\r\n\r\n.navbar {\r\n    min-height: 133px;\r\n    font-size: 17px;\r\n    box-shadow: none !important;\r\n}\r\n\r\n.navbar .container-fluid {\r\n    padding-left: 15px;\r\n    margin-right: auto;\r\n    margin-left: auto;\r\n    margin-top: 27px;\r\n}\r\n\r\n\r\n\r\n.navbar-brand {\r\n    height: 65px;\r\n}\r\n .tinyheader .navbar-brand {\r\n    height: 60px;\r\n}\r\n\r\n@media (min-width: 992px) {\r\n    .logo {\r\n        margin-right: 45px !important;\r\n        padding-top: 0px\r\n    }\r\n}\r\n\r\n.main-banner {\r\n    height: 482px;\r\n}\r\n\r\n.featured-companies .featured-company__panel-footer {\r\n    padding: 0 0px;\r\n    height: 40px;\r\n}\r\n\r\n.featured-companies .featured-company__panel {\r\n    border-radius: 4px;\r\n    border: none;\r\n}\r\n\r\n.featured-companies__name span {\r\n    width: 90px;\r\n    font-size: 12px;\r\n}\r\n\r\n.featured-companies__jobs {\r\n    font-size: 12px;\r\n    padding-right: 2px;\r\n}\r\n\r\n.middle-banner {\r\n    display: none;\r\n}\r\n\r\n.main-sections__alert {\r\n    display: block;\r\n}\r\n\r\n.footer {\r\n    background-color: #413D3C;\r\n}\r\n\r\n.listing-item__jobs {\r\n    border-radius: 0px;\r\n}\r\n\r\n.listing-item__employment-type {\r\n    border-radius: 4px;\r\n    background: #F7F7F7;\r\n    border: 1px solid #E2E2E2;\r\n}\r\n\r\n.listing__latest .listing-item__employment-type,\r\n.listing__latest .listing-item__title>.link {\r\n    color: #ed174b;\r\n}\r\n\r\n.navbar .navbar-right .logout_btn {\r\n    background: #fff;\r\n    height: 25px;\r\n    line-height: 22px;\r\n    color: #fff;\r\n    padding: 0px 10px;\r\n    border: 1px solid #ed174b;\r\n    font-size: 16px\r\n}\r\n\r\n.navbar .navbar-right .signup_btn {\r\n    background: #fff;\r\n    height: 25px;\r\n    line-height: 22px;\r\n    color: #005689;\r\n    border: 1px solid #005689;\r\n    padding: 0px 10px;\r\n    font-size: 16px\r\n}\r\n\r\n/******************************/\r\n\r\n@media all and (max-width: 992px) {\r\n    .navbar {\r\n        min-height: 70px;\r\n    }\r\n}\r\n\r\n.navbar .container {\r\n    position: relative;\r\n}\r\n\r\n@media all and (max-width: 992px) {\r\n    .navbar .container {\r\n        width: 100%;\r\n        padding: 0;\r\n		  margin-top:0\r\n    }\r\n}\r\n\r\n.navbar .navbar-left {\r\n    display: inline-block;\r\n}\r\n\r\n@media all and (min-width: 992px) {\r\n    .navbar .navbar-left {\r\n        padding: 5px 0 0;\r\n        margin: 0px 0px 0px;\r\n        /*float: right !important; */\r\n        margin-right: -15px;\r\n    }\r\n\r\n    .navbar-collapse {\r\n        padding-right: 0px;\r\n        padding-left: 0px;\r\n    }\r\n}\r\n\r\n@media all and (max-width: 992px) {\r\n    .navbar .navbar-left {\r\n        margin: 0;\r\n        padding: 15px 0 0;\r\n    }\r\n}\r\n\r\n.navbar .navbar-left>.navbar__item {\r\n    padding: 10px 0px 10px 40px;\r\n}\r\n\r\nul.nav .navbar__item:last-child,\r\nul.nav .navbar__item:last-child() {}\r\n\r\n@media all and (min-width: 992px) {\r\n    .navbar .navbar-left>.navbar__item {\r\n        padding-top: 20px;\r\n        padding-bottom: 10px;\r\n    }\r\n}\r\n\r\n@media all and (max-width: 992px) {\r\n    .navbar .navbar-left .navbar__item {\r\n        padding-left: 10px;\r\n    }\r\n}\r\n\r\n.navbar .navbar-left .navbar__item.active>.navbar__link,\r\n.navbar .navbar-left .navbar__item.active>.navbar__link:hover {\r\n    background: none;\r\n    color: #ed174b;\r\n}\r\n\r\n.navbar .navbar-left .navbar__item.active>.navbar__link span,\r\n.navbar .navbar-left .navbar__item.active>.navbar__link:hover span {\r\n    padding-bottom: 2px;\r\n    display: inline-block;\r\n    border-bottom: none;\r\n}\r\n\r\n@media all and (min-width: 992px) {\r\n    .navbar .navbar-left .navbar__item:first-child {\r\n        padding-left: 0;\r\n    }\r\n}\r\n\r\n.navbar .navbar-left .navbar__item .navbar__link {\r\n    padding: 0;\r\n    color: #262626;\r\n}\r\n\r\n.navbar .navbar-left .navbar__item .navbar__link:hover {\r\n    background: none;\r\n    color: #ed174b;\r\n}\r\n\r\n.navbar .navbar-left .navbar__item .navbar__link.hover+.dropdown-menu {\r\n    display: block;\r\n}\r\n\r\n.navbar .navbar-left .navbar__item.dropdown {\r\n    position: static;\r\n}\r\n\r\n@media all and (min-width: 992px) {\r\n    .navbar .navbar-left .navbar__item.dropdown>.navbar__link:after {\r\n        content: \'\';\r\n        display: inline-block;\r\n        position: relative;\r\n        border-style: solid;\r\n        border-width: 1px 1px 0 0;\r\n        height: 6px;\r\n        width: 6px;\r\n        margin-left: 6px;\r\n        top: -3px;\r\n        -moz-transform: rotate(135deg);\r\n        -webkit-transform: rotate(135deg);\r\n        -o-transform: rotate(135deg);\r\n        -ms-transform: rotate(135deg);\r\n        transform: rotate(135deg);\r\n    }\r\n}\r\n\r\n.navbar .navbar-left .navbar__item.dropdown>.dropdown-menu {\r\n    max-width: