vbar-right .navbar__item .navbar__link.btn__blue {\r\n        color: #fff;\r\n        background:#ed174b;\r\n        padding: 8px 20px;\r\n        border-radius: 4px;\r\n    }\r\n\r\n.registration-page .left-section-wrp.loginpage {\r\n    padding: 0;\r\n}\r\n\r\n.connexion-social.text-center#information {\r\n    padding-top: 0px!important;\r\n}\r\n.registration-page #information h3 {\r\n\r\n    margin-top: 0;\r\n   \r\n}\r\n\r\n.navbar-collapse {\r\n   \r\n    top: 90px;\r\n}\r\n \r\n\r\n\r\n.registration-page .content-card {\r\n\r\n    padding: 0;\r\n    \r\n}\r\n\r\n\r\n.registration-page.px\r\n {\r\n     \r\n        padding-top: 0;\r\n       \r\n    }\r\n\r\n\r\n\r\n\r\n.listing-item__title {\r\n    max-height: max-content!important;\r\n   \r\n}\r\n\r\n.burger-button__wrapper {\r\n \r\n    margin-top: 22px;\r\n    padding: 15px 10px;\r\n  \r\n}\r\n\r\n.tinyheader .job-top-wrapper .be-first-to-apply {\r\n\r\n    display: block;\r\n    clear: both;\r\n}\r\n\r\n.tinyheader .job-left-side .btn, .tinyheader .details-footer .btn {\r\n    width: auto;\r\n    \r\n}\r\n\r\n.share-container:hover .share-icons {\r\n\r\n    right: -40px;\r\n    left: auto;\r\n}\r\n.tinyheader .results {\r\n    margin-top: 0;\r\n}\r\n\r\n.tinyheader .details-header.page-detail-annonce .details-header__title {\r\n	 font-size: 24px;}\r\n.tinyheader .refine-search {\r\n \r\n    background: transparent;\r\n    border: 0;\r\n}\r\n.filters-actions {\r\n   \r\n    flex-direction: column;\r\n}\r\n.filters-container {\r\n     margin-top: 0!important;\r\n    \r\n}\r\n\r\n.btn-export-pdf {\r\n        padding: 8px 16px !important;\r\n    }\r\n\r\n.recrutement_page #pagination-container .pagination {\r\n  \r\n    display: flex;\r\n    flex-wrap: wrap;\r\n}\r\n\r\n.applicants {\r\n  \r\n    scrollbar-color: #2563eb  #2563eb;\r\n}\r\n\r\n\r\n\r\n#applicants-container-links {\r\n    display: flex;\r\n    font-size: 11px;\r\n    justify-content: space-around;\r\n	 padding-top: 15px;\r\n}\r\n\r\n.btn-next-Nouveau { position:relative}\r\n.btn-next-Nouveau:after {\r\n        position: absolute;\r\n        bottom: -4px;\r\n        height: 4px;\r\n        width: 100%;\r\n        background: #ee810c;\r\n        border-radius: 5px;\r\n        content: \"\";\r\n        left: 0;\r\n    }\r\n\r\n\r\n.btn-next-Interview { position:relative}\r\n.btn-next-Interview:after {\r\n        position: absolute;\r\n        bottom: -4px;\r\n        height: 4px;\r\n        width: 100%;\r\n        background: #2563eb;\r\n        border-radius: 5px;\r\n        content: \"\";\r\n        left: 0;\r\n    }\r\n\r\n\r\n#applicants-container-links a:nth-child(3) { position:relative}\r\n#applicants-container-links a:nth-child(3):after {\r\n        position: absolute;\r\n        bottom: -4px;\r\n        height: 4px;\r\n        width: 100%;\r\n        background: #8bc34a;\r\n        border-radius: 5px;\r\n        content: \"\";\r\n        left: 0;\r\n    }\r\n\r\n\r\n#applicants-container-links a:nth-child(4) { position:relative}\r\n#applicants-container-links a:nth-child(4):after {\r\n        position: absolute;\r\n        bottom: -4px;\r\n        height: 4px;\r\n        width: 100%;\r\n        background: #cc3a3a;\r\n        border-radius: 5px;\r\n        content: \"\";\r\n        left: 0;\r\n    }\r\n\r\n.applicants-wrapper {\r\n  display: flex;\r\n  overflow-x: auto;\r\n  scroll-behavior: smooth; /* bonus natif */\r\n  width: 100%;\r\n}\r\n\r\n.applicant-status {\r\n  min-width: 100vw; /* 1 section = 1 écran */\r\n  flex-shrink: 0;\r\n  padding: 20px;\r\n}\r\n\r\n}\r\n/*\r\n.blog_page .listing-item__logo, .blog__content--image { display:none; visibility:0}*/\r\n\r\n.quick-search__frontpage  {    position: absolute;\r\nz-index: 999;\r\nbottom: 0; width:100%}\r\n\r\n.slide img {\r\n    width: 100%;\r\n    display: block;\r\n    height: auto;\r\n    filter: blur(50px);\r\n    display: none;\r\n}');
