(1239, 'theme_custom_js_Jobsquare', '<script>\r\n \r\nwindow.onscroll = function() {scrollFunction()};\r\n\r\nfunction scrollFunction() {\r\n    if (document.body.scrollTop > 120 || document.documentElement.scrollTop > 120) {\r\n        document.getElementById(\"gotop\").style.display = \"block\";\r\n    } else {\r\n        document.getElementById(\"gotop\").style.display = \"none\";\r\n    }\r\n}\r\n\r\n// When the user clicks on the button, scroll to the top of the document\r\nfunction topFunction() {\r\n    document.body.scrollTop = 0;\r\n    document.documentElement.scrollTop = 0;\r\n}\r\n\r\n</script>\r\n\r\n<script>\r\ndocument.addEventListener(\"DOMContentLoaded\", function () {\r\n  const stickyTop = document.querySelector(\'#stickytop\');\r\n  const showAfter = 200; // px\r\n\r\n  if (!stickyTop) return;\r\n\r\n  window.addEventListener(\'scroll\', () => {\r\n    const scrollY = window.scrollY || window.pageYOffset;\r\n\r\n    if (scrollY > showAfter) {\r\n      stickyTop.classList.add(\'is-visible\');\r\n    } else {\r\n      stickyTop.classList.remove(\'is-visible\');\r\n    }\r\n  });\r\n});\r\n</script>'),
(1240, 'theme_font_Jobsquare', '\"Open Sans\", sans-serif'),
(1241, 'theme_footer_Jobsquare', '<div>\r\n<div>\r\n<ul>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/\">Accueil</a></li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/contact/\">Contact</a></li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/about/\">A propos</a></li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/terms-of-use/\">Termes &amp; Conditions</a></li>\r\n</ul>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>Employeur</li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/add-listing/?listing_type_id=Job\">Publier une annonce</a></li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/resumes/\">Trouver un CV</a></li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/login/\">Connexion</a></li>\r\n</ul>\r\n</div>\r\n<div>\r\n<ul>\r\n<li>Chercheur d\'emploi</li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/jobs/\">Trouver un emploi</a></li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/trainings\">Trouver une formation</a></li>\r\n<li><a class=\"footer-nav__link\" href=\"$GLOBALS.site_url/login/\">Connexion</a></li>\r\n</ul>\r\n</div>\r\n<div>\r\n<ul>\r\n<li><a title=\"Emploi Maroc\" href=\"https://www.facebook.com/jobsquare.ma/\" target=\"_blank\">Facebook</a></li>\r\n<li><a class=\"footer-nav__link footer-nav__link-social footer-nav__link-in\" title=\"LinkedIn\" href=\"https://www.linkedin.com/company/jobsquarema/\" target=\"_blank\">LinkedIn</a></li>\r\n</ul>\r\n</div>\r\n</div>\r\n<div style=\"width: 100%; clear: both;\">&copy; 2025-$current_year <a title=\"Emploi Maroc, travail Maroc, recrutement Maroc\" href=\"https://www.jobsquare.ma\" target=\"_blank\">Jobsquare.ma</a></div>'),
